"""Evaluator contract tests only: generated bytes/vectors are explicit fixtures."""
from contextlib import redirect_stdout
import hashlib
import io
import json
from pathlib import Path
import sys
import tempfile
import unittest
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT))
from scripts import evaluate_pet_quality as evaluator


class PetQualityEvaluatorTests(unittest.TestCase):
    def setUp(self):
        directory = ROOT / "tmp" / "pet-quality-tests"
        directory.mkdir(parents=True, exist_ok=True)
        self.temp = tempfile.TemporaryDirectory(dir=directory)
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.feature_version = "fixture-features-v1"

    def asset(self, asset_id, split="holdout", individual=None, sequence=None):
        content = ("explicit evaluator fixture bytes: " + asset_id).encode()
        path = self.root / (asset_id + ".bin")
        path.write_bytes(content)
        value = {"id": asset_id, "path": path.name, "sha256": hashlib.sha256(content).hexdigest(),
                 "sourceUrl": "https://example.invalid/fixture/" + asset_id,
                 "license": "Test fixture, not model acceptance", "split": split}
        if individual:
            value["individualId"] = individual
        if sequence:
            value["sequenceId"] = sequence
        return value

    def feature(self, vector, species=None):
        value = {"vector": vector, "featureVersion": self.feature_version}
        if species:
            value["species"] = species
        return value

    def sample(self):
        manifest = {"schemaVersion": 1, "benchmarkKind": "semantic-smoke", "modelManifestVersion": "fixture-model-v1",
                    "featureVersion": self.feature_version, "featureBundle": {},
                    "assets": [self.asset(value) for value in ("gallery-a", "gallery-b", "query-source")],
                    "gallery": [{"mediaId": "a", "assetId": "gallery-a"}, {"mediaId": "b", "assetId": "gallery-b"}],
                    "queries": [
                        {"queryId": "photo", "split": "holdout", "mode": "photo", "assetId": "query-source", "positiveIds": ["a"]},
                        {"queryId": "text", "split": "holdout", "mode": "text", "description": "fixture markings", "positiveIds": ["b"]},
                        {"queryId": "combined", "split": "holdout", "mode": "combined", "assetId": "query-source", "description": "fixture markings", "positiveIds": ["b"]},
                        {"queryId": "no-match", "split": "holdout", "mode": "text", "description": "unrelated fixture", "positiveIds": []},
                    ]}
        bundle = {"schemaVersion": 1, "modelManifestVersion": "fixture-model-v1", "featureVersion": self.feature_version,
                  "provenance": {"kind": "fixture", "runId": "unit-tests-not-models"},
                  "media": {"a": [self.feature([1., 0.], "cat")], "b": [self.feature([0.6, 0.8], "cat")]},
                  "queries": {
                      "photo": {"features": [self.feature([1., 0.], "cat")]},
                      "text": {"features": [self.feature([0., 1.])]},
                      "combined": {"features": [self.feature([1., 0.], "cat")], "descriptionFeature": self.feature([0., 1.])},
                      "no-match": {"features": [self.feature([-1., -1.])]},
                  }}
        return manifest, bundle

    def write(self, manifest, bundle):
        bundle_path = self.root / "features.json"
        bundle_path.write_text(json.dumps(bundle), encoding="utf-8")
        manifest["featureBundle"] = {"path": bundle_path.name, "sha256": evaluator.sha256(bundle_path)}
        path = self.root / "manifest.json"
        path.write_text(json.dumps(manifest), encoding="utf-8")
        return path

    def identity_sample(self, count=50):
        manifest, bundle = self.sample()
        manifest.update(benchmarkKind="pet-identity", assets=[], gallery=[], queries=[],
                        identityLabels={"humanVerified": True, "labeler": "unit-test-fixture", "method": "Synthetic labels testing validation only"})
        bundle.update(media={}, queries={})
        for i in range(count):
            identity = f"individual-{i}"
            source_id, gallery_id, query_id = f"source-{i}", f"gallery-{i}", f"query-{i}"
            manifest["assets"] += [self.asset(source_id, individual=identity), self.asset(gallery_id, individual=identity)]
            manifest["gallery"].append({"mediaId": gallery_id, "assetId": gallery_id})
            manifest["queries"].append({"queryId": query_id, "split": "holdout", "mode": "photo", "assetId": source_id, "positiveIds": [gallery_id]})
            bundle["media"][gallery_id] = [self.feature([1., 0.], "cat")]
            bundle["queries"][query_id] = {"features": [self.feature([1., 0.], "cat")]}
        return manifest, bundle

    def assert_invalid(self, manifest, bundle, code):
        with self.assertRaises(evaluator.InvalidBenchmark) as caught:
            evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(caught.exception.code, code)

    def test_all_modes_use_production_scoring_and_never_claim_acceptance(self):
        manifest, bundle = self.sample()
        manifest["qualityGates"] = {"recallAt1": 1, "recallAt5": 1}
        original = evaluator.Workers._query_result
        calls = []

        def capture(worker, operation, detection):
            calls.append(operation["queryId"])
            return original(worker, operation, detection)

        with patch.object(evaluator.Workers, "_query_result", capture):
            report, code = evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(code, 0)
        self.assertEqual(calls, [q["queryId"] for q in manifest["queries"]])
        cases = {case["queryId"]: case for case in report["cases"]}
        self.assertEqual(cases["photo"]["rankedIds"], ["a", "b"])
        self.assertEqual(cases["text"]["rankedIds"], ["b"])
        self.assertEqual(cases["combined"]["rankedIds"], ["b", "a"])
        self.assertEqual(cases["combined"]["scores"], {"b": 0.7, "a": 0.5})
        self.assertEqual(cases["no-match"]["rankedIds"], [])
        self.assertEqual(report["threshold"], 0.2)
        self.assertEqual(report["evidenceScope"], "fixture-only")
        self.assertFalse(any(report["claims"].values()))
        self.assertNotIn('"vector"', json.dumps(report))

    def test_feature_error_queries_remain_in_recall_and_negative_denominators(self):
        manifest, bundle = self.sample()
        for query_id in ("text", "no-match"):
            bundle["queries"][query_id] = {"features": [], "error": {"code": "INFERENCE_FAILED", "message": "Explicit fixture failure"}}
        report, code = evaluator.evaluate(self.write(manifest, bundle))
        metric = report["bySplit"]["holdout"]["byMode"]["text"]
        self.assertEqual(code, 1)
        self.assertEqual(len(report["cases"]), 4)
        self.assertEqual(metric["positiveQueries"], 1)
        self.assertEqual(metric["recallAt1"], 0)
        self.assertEqual(metric["noMatchQueries"], 1)
        self.assertEqual(metric["noMatchInferenceFailures"], 1)
        self.assertEqual(metric["failedQueries"], 2)

    def test_incomplete_gallery_is_not_silently_dropped_from_scoring(self):
        manifest, bundle = self.sample()
        bundle["media"]["b"] = []
        bundle["mediaErrors"] = {"b": {"code": "INFERENCE_FAILED", "message": "Fixture gallery failure"}}
        report, code = evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(code, 1)
        self.assertEqual(report["failedQueries"], 4)
        self.assertEqual(report["bySplit"]["holdout"]["all"]["positiveQueries"], 3)
        self.assertTrue(all(case["error"]["code"] == "GALLERY_INFERENCE_FAILED" for case in report["cases"]))

    def test_worker_exception_becomes_a_case_failure_without_skipping_later_queries(self):
        manifest, bundle = self.sample()
        original = evaluator.Workers._query_result

        def fail_one(worker, operation, detection):
            if operation["queryId"] == "photo":
                raise RuntimeError("Explicit worker fixture exception")
            return original(worker, operation, detection)

        with patch.object(evaluator.Workers, "_query_result", fail_one):
            report, code = evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(code, 1)
        self.assertEqual(report["failedQueries"], 1)
        self.assertEqual(report["bySplit"]["holdout"]["all"]["positiveQueries"], 3)
        self.assertEqual(report["bySplit"]["holdout"]["all"]["recallAt1"], 2 / 3)

    def test_no_match_false_positives_fail_the_frozen_gate(self):
        manifest, bundle = self.sample()
        manifest["queries"] = [q for q in manifest["queries"] if q["mode"] == "text"]
        bundle["queries"] = {key: value for key, value in bundle["queries"].items() if key in ("text", "no-match")}
        bundle["queries"]["no-match"]["features"] = [self.feature([1., 0.])]
        manifest["qualityGates"] = {"recallAt1": 1, "maxNoMatchFalsePositiveRate": 0}
        report, code = evaluator.evaluate(self.write(manifest, bundle))
        metric = report["bySplit"]["holdout"]["byMode"]["text"]
        self.assertEqual(code, 1)
        self.assertEqual(metric["falsePositiveQueries"], 1)
        self.assertEqual(metric["noMatchQueries"], 1)
        self.assertFalse(report["qualityGatesPassed"])

    def test_calibration_cannot_satisfy_holdout_gates(self):
        manifest, bundle = self.sample()
        for asset in manifest["assets"]:
            asset["split"] = "calibration"
        for query in manifest["queries"]:
            query["split"] = "calibration"
        manifest["qualityGates"] = {"recallAt1": 1}
        report, code = evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(code, 1)
        self.assertEqual(report["bySplit"]["calibration"]["all"]["recallAt1"], 1)
        self.assertIsNone(report["bySplit"]["holdout"]["all"]["recallAt1"])
        self.assertFalse(report["qualityGatesPassed"])

    def test_missing_or_extra_feature_ids_are_invalid(self):
        for collection in ("media", "queries"):
            for operation in ("missing", "extra"):
                with self.subTest(collection=collection, operation=operation):
                    manifest, bundle = self.sample()
                    if operation == "missing":
                        bundle[collection].pop(next(iter(bundle[collection])))
                    else:
                        bundle[collection]["invented-id"] = []
                    self.assert_invalid(manifest, bundle, "FEATURE_IDS_MISMATCH")

    def test_empty_features_without_explicit_failure_are_invalid(self):
        manifest, bundle = self.sample()
        bundle["queries"]["photo"]["features"] = []
        self.assert_invalid(manifest, bundle, "MISSING_FEATURES")

    def test_feature_version_dimensions_finiteness_and_zero_vectors_are_checked(self):
        mutations = [
            ({"featureVersion": "wrong-version"}, "VERSION_MISMATCH"),
            ({"vector": [1., 0., 0.]}, "VECTOR_DIMENSION_MISMATCH"),
            ({"vector": [float("nan"), 0.]}, "INVALID_VECTOR"),
            ({"vector": [float("inf"), 0.]}, "INVALID_VECTOR"),
            ({"vector": [True, 0.]}, "INVALID_VECTOR"),
            ({"vector": [0., 0.]}, "INVALID_VECTOR"),
            ({"vector": [1e308, 0.]}, "INVALID_VECTOR"),
            ({"vector": [10**400, 0.]}, "INVALID_VECTOR"),
        ]
        for change, code in mutations:
            with self.subTest(code=code, change=str(change)):
                manifest, bundle = self.sample()
                bundle["queries"]["photo"]["features"][0].update(change)
                self.assert_invalid(manifest, bundle, code)

    def test_versions_and_combined_input_cannot_be_silently_ignored(self):
        manifest, bundle = self.sample()
        bundle["modelManifestVersion"] = "other-model"
        self.assert_invalid(manifest, bundle, "VERSION_MISMATCH")
        manifest, bundle = self.sample()
        bundle["queries"]["combined"].pop("descriptionFeature")
        self.assert_invalid(manifest, bundle, "MISSING_FEATURES")
        manifest, bundle = self.sample()
        manifest["queries"][0]["description"] = "must not be ignored"
        self.assert_invalid(manifest, bundle, "MODE_MISMATCH")

    def test_asset_source_license_and_sha_are_required(self):
        for field in ("sourceUrl", "license"):
            with self.subTest(field=field):
                manifest, bundle = self.sample()
                manifest["assets"][0][field] = ""
                self.assert_invalid(manifest, bundle, "INVALID_TEXT")
        manifest, bundle = self.sample()
        path = self.write(manifest, bundle)
        (self.root / manifest["assets"][0]["path"]).write_bytes(b"changed fixture")
        with self.assertRaises(evaluator.InvalidBenchmark) as caught:
            evaluator.evaluate(path)
        self.assertEqual(caught.exception.code, "HASH_MISMATCH")

    def test_changed_bundle_bytes_and_duplicate_json_keys_are_rejected(self):
        manifest, bundle = self.sample()
        path = self.write(manifest, bundle)
        (self.root / "features.json").write_text("{}", encoding="utf-8")
        with self.assertRaises(evaluator.InvalidBenchmark) as caught:
            evaluator.evaluate(path)
        self.assertEqual(caught.exception.code, "HASH_MISMATCH")
        path.write_text('{"schemaVersion":1,"schemaVersion":1}', encoding="utf-8")
        with self.assertRaises(evaluator.InvalidBenchmark) as caught:
            evaluator.evaluate(path)
        self.assertEqual(caught.exception.code, "DUPLICATE_JSON_KEY")

    def test_positive_ids_must_exactly_reference_gallery_members(self):
        manifest, bundle = self.sample()
        manifest["queries"][0]["positiveIds"] = ["not-in-gallery"]
        self.assert_invalid(manifest, bundle, "INVALID_POSITIVES")

    def test_malformed_reference_types_produce_validation_errors(self):
        for target in ("gallery", "query"):
            with self.subTest(target=target):
                manifest, bundle = self.sample()
                row = manifest["gallery"][0] if target == "gallery" else manifest["queries"][0]
                row["assetId"] = []
                self.assert_invalid(manifest, bundle, "INVALID_ID")

    def test_identity_requires_human_attestation_and_at_least_fifty_sources(self):
        manifest, bundle = self.identity_sample(49)
        self.assert_invalid(manifest, bundle, "IDENTITY_HOLDOUT_UNAVAILABLE")
        manifest, bundle = self.identity_sample()
        manifest["identityLabels"]["humanVerified"] = False
        self.assert_invalid(manifest, bundle, "HUMAN_LABELS_REQUIRED")
        manifest["identityLabels"]["humanVerified"] = True
        report, code = evaluator.evaluate(self.write(manifest, bundle))
        self.assertEqual(code, 0)
        self.assertEqual(report["identityHoldoutUniqueSources"], 50)
        self.assertEqual(report["evidenceScope"], "fixture-only")
        self.assertFalse(report["claims"]["identityAcceptance"])

    def test_identity_rejects_source_self_match_even_with_another_asset_id(self):
        for alias in (False, True):
            with self.subTest(alias=alias):
                manifest, bundle = self.identity_sample()
                query = manifest["queries"][0]
                if not alias:
                    query["assetId"] = "gallery-0"
                else:
                    source, gallery = manifest["assets"][:2]
                    source.update(path=gallery["path"], sha256=gallery["sha256"])
                self.assert_invalid(manifest, bundle, "SELF_MATCH_LEAKAGE")

    def test_identity_rejects_individual_sequence_and_hash_split_leakage(self):
        for key in ("individualId", "sequenceId", "sha256"):
            with self.subTest(key=key):
                manifest, bundle = self.identity_sample()
                extra = self.asset("calibration-extra", "calibration", "calibration-individual")
                first = manifest["assets"][0]
                if key == "individualId":
                    extra[key] = first[key]
                elif key == "sequenceId":
                    first[key] = extra[key] = "shared-sequence"
                else:
                    extra.update(path=first["path"], sha256=first["sha256"])
                manifest["assets"].append(extra)
                self.assert_invalid(manifest, bundle, "SPLIT_LEAKAGE")

    def test_identity_labels_define_all_positive_ids(self):
        manifest, bundle = self.identity_sample()
        manifest["queries"][0]["positiveIds"] = []
        self.assert_invalid(manifest, bundle, "POSITIVE_LABEL_MISMATCH")

    def test_cli_writes_failures_and_returns_nonzero_without_running_models(self):
        manifest, bundle = self.sample()
        manifest["qualityGates"] = {"recallAt1": 1}
        bundle["queries"]["photo"]["features"] = [self.feature([-1., 0.])]
        path = self.write(manifest, bundle)
        output = self.root / "report.json"
        with redirect_stdout(io.StringIO()), patch("socket.create_connection", side_effect=AssertionError("Network is forbidden")):
            code = evaluator.main([str(path), "--output", str(output)])
        self.assertEqual(code, 1)
        self.assertEqual(json.loads(output.read_text())["status"], "quality_gate_failed")
        path.write_text("{}", encoding="utf-8")
        with redirect_stdout(io.StringIO()):
            code = evaluator.main([str(path), "--output", str(output)])
        self.assertEqual(code, 2)
        self.assertEqual(json.loads(output.read_text())["status"], "invalid_manifest")


if __name__ == "__main__":
    unittest.main()
